css:
.f1 { display: flex; align-items: center; justify-content: space-between; width: 920px; max-width: 100%; padding: 22px 28px; box-sizing: border-box; background: #f9fafb; border-top: 1px solid #e5e7eb; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.f1-copy { margin: 0; font-size: 13px; color: #6b7280; }
.f1-links { display: flex; gap: 24px; }
.f1-links a { font-size: 13px; color: #4b5563; text-decoration: none; }
.f1-links a:hover { color: #111827; text-decoration: underline; }

.f2 { width: 920px; max-width: 100%; padding: 36px 28px 20px; box-sizing: border-box; background: #fff; border-top: 1px solid #e5e7eb; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.f2-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 32px; }
.f2-logo { margin: 0 0 8px; font-size: 20px; font-weight: 800; color: #111827; }
.f2-text { margin: 0; max-width: 280px; font-size: 13px; line-height: 1.8; color: #6b7280; }
.f2-col { display: flex; flex-direction: column; gap: 10px; }
.f2-head { margin: 0 0 4px; font-size: 13px; font-weight: 700; color: #111827; }
.f2-col a { font-size: 13px; color: #6b7280; text-decoration: none; }
.f2-col a:hover { color: #111827; }
.f2-copy { margin: 28px 0 0; padding-top: 16px; border-top: 1px solid #f1f5f9; font-size: 12px; color: #9ca3af; }

.f3 { width: 920px; max-width: 100%; padding: 36px 28px 28px; box-sizing: border-box; background: #fff; border-top: 1px solid #e5e7eb; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.f3-logo { margin: 0 0 16px; font-size: 22px; font-weight: 800; color: #111827; }
.f3-links { display: flex; justify-content: center; gap: 26px; margin-bottom: 20px; }
.f3-links a { font-size: 14px; color: #4b5563; text-decoration: none; }
.f3-copy { margin: 0; font-size: 12px; color: #9ca3af; }

.f4 { display: flex; align-items: center; justify-content: space-between; width: 920px; max-width: 100%; padding: 28px; box-sizing: border-box; background: #f9fafb; border-top: 1px solid #e5e7eb; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.f4-logo { margin: 0 0 4px; font-size: 20px; font-weight: 800; color: #111827; }
.f4-copy { margin: 0; font-size: 12px; color: #9ca3af; }
.f4-social { display: flex; gap: 10px; }
.f4-social a { width: 38px; height: 38px; border-radius: 50%; background: #111827; color: #fff; font-size: 14px; font-weight: 700; line-height: 38px; text-align: center; text-decoration: none; }
.f4-social a:hover { background: #4f46e5; }

.f5 { display: flex; align-items: center; justify-content: space-between; gap: 40px; width: 920px; max-width: 100%; padding: 32px 28px; box-sizing: border-box; background: #eef2ff; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.f5-title { margin: 0 0 10px; font-size: 15px; font-weight: 700; color: #312e81; }
.f5-form { display: flex; gap: 8px; }
.f5-input { width: 260px; height: 40px; padding: 0 14px; box-sizing: border-box; border: 1px solid #c7d2fe; border-radius: 8px; background: #fff; font-size: 14px; }
.f5-btn { height: 40px; padding: 0 20px; border: 0; border-radius: 8px; background: #4f46e5; color: #fff; font-size: 14px; font-weight: 600; cursor: pointer; }
.f5-links { display: flex; flex-direction: column; gap: 10px; }
.f5-links a { font-size: 13px; color: #4338ca; text-decoration: none; }

.f6 { width: 920px; max-width: 100%; padding: 32px 28px 20px; box-sizing: border-box; background: #111827; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.f6-main { display: flex; align-items: center; justify-content: space-between; padding-bottom: 20px; border-bottom: 1px solid #374151; }
.f6-logo { margin: 0; font-size: 20px; font-weight: 800; letter-spacing: 2px; color: #f9fafb; }
.f6-logo span { color: #22d3ee; }
.f6-links { display: flex; gap: 26px; }
.f6-links a { font-size: 14px; color: #9ca3af; text-decoration: none; }
.f6-links a:hover { color: #22d3ee; }
.f6-copy { margin: 16px 0 0; font-size: 12px; color: #6b7280; }

.f7 { display: flex; align-items: center; justify-content: center; gap: 10px; width: 920px; max-width: 100%; padding: 20px; box-sizing: border-box; background: #fff; border-top: 1px solid #f1f5f9; font-size: 12px; color: #9ca3af; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.f7 a { color: #6b7280; text-decoration: none; }
.f7 a:hover { color: #111827; text-decoration: underline; }

.f8 { width: 920px; max-width: 100%; overflow: hidden; border-radius: 12px; background: #fff; border: 1px solid #e5e7eb; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Hiragino Sans', 'Noto Sans JP', sans-serif; }
.f8-cta { display: flex; align-items: center; justify-content: space-between; padding: 30px 32px; background: linear-gradient(120deg, #4f46e5, #7c3aed); color: #fff; }
.f8-title { margin: 0 0 4px; font-size: 20px; font-weight: 800; }
.f8-text { margin: 0; font-size: 14px; opacity: 0.9; }
.f8-btn { padding: 12px 24px; border-radius: 999px; background: #fff; color: #4f46e5; font-size: 14px; font-weight: 700; text-decoration: none; }
.f8-bottom { display: flex; align-items: center; justify-content: space-between; padding: 16px 32px; font-size: 12px; color: #6b7280; }
.f8-links { display: flex; gap: 20px; }
.f8-links a { color: #6b7280; text-decoration: none; }
